 const [data,setData]=useState<State>(emptyState),[month,setMonth]=useState(()=>today().slice(0,7)),[revision,setRevision]=useState<string|null>(null),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(''),[hidden,setHidden]=useState(false),[view,setView]=useState<View>('dashboard'),[modal,setModal]=useState<Modal>(null),[editEntry,setEditEntry]=useState<Entry|null>(null),[editCard,setEditCard]=useState<Card|null>(null),[search,setSearch]=useState(''),[categoryFilter,setCategoryFilter]=useState('all'),[methodFilter,setMethodFilter]=useState('all'),[mobileNav,setMobileNav]=useState(false),[simValue,setSimValue]=useState(''),[simParts,setSimParts]=useState(12),[offline,setOffline]=useState(false),[dark,setDark]=useState(false),[installPrompt,setInstallPrompt]=useState<InstallPromptEvent|null>(null),[imported,setImported]=useState<Entry[]>([]);const lock=useRef(false);
 const current=()=>today().slice(0,7);
 async function load(){setLoading(true);setError('');try{const r=await fetch('/api/finance',{cache:'no-store'});if(r.status===401){location.assign('/entrar');return;}const body=await r.json();if(!r.ok)throw Error(body.error);setData(normalizeState(body.data));setRevision(body.revision);setOffline(false);}catch(e){setOffline(!navigator.onLine);setError(navigator.onLine?(e as Error).message:'Sem conexão. Conecte-se à internet para abrir seus registros privados.');}finally{setLoading(false);}}
 useEffect(()=>{const savedTheme=localStorage.getItem('rf-theme')==='dark';document.documentElement.classList.toggle('dark',savedTheme);requestAnimationFrame(()=>setDark(savedTheme));void Promise.resolve().then(load);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const install=(event:Event)=>{event.preventDefault();setInstallPrompt(event as InstallPromptEvent);};window.addEventListener('beforeinstallprompt',install);const online=()=>setOffline(false);const offlineEvent=()=>setOffline(true);window.addEventListener('online',online);window.addEventListener('offline',offlineEvent);return()=>{window.removeEventListener('beforeinstallprompt',install);window.removeEventListener('online',online);window.removeEventListener('offline',offlineEvent);};},[]);
 async function save(next:State,message='Alterações salvas'){if(lock.current)return false;lock.current=true;setBusy(true);try{if(!navigator.onLine){setOffline(true);toast.error('Sem conexão. Conecte-se à internet para salvar.');return false;}const r=await fetch('/api/finance',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:next,revision})});const body=await r.json();if(!r.ok)throw Error(body.error);setData(next);setRevision(body.revision);toast.success(message);return true;}catch(e){toast.error((e as Error).message);return false;}finally{lock.current=false;setBusy(false);}}
 const totals=summary(data,month),previous=summary(data,addMonths(month,-1)),fmt=(n:number)=>hidden?'R$ ••••':money(n),expenses=data.entries.filter(e=>e.kind==='expense'),monthEntries=data.entries.filter(e=>amountAt(e,month)>0),cardTotal=(id:string)=>expenses.filter(e=>e.cardId===id).reduce((sum,e)=>sum+amountAt(e,month),0);
