 const filtered=monthEntries.filter(e=>(categoryFilter==='all'||e.category===categoryFilter)&&(methodFilter==='all'||e.method===methodFilter)&&(`${e.name} ${e.description} ${e.borrower}`.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date));
 const borrowers=Object.entries(expenses.filter(e=>e.borrower).reduce<Record<string,number>>((a,e)=>{a[e.borrower]=(a[e.borrower]||0)+amountAt(e,month);return a;},{})).sort((a,b)=>b[1]-a[1]);
 const subscriptions=expenses.filter(e=>e.subscription||e.category==='Assinaturas').filter(e=>amountAt(e,month)>0),subscriptionsTotal=subscriptions.reduce((s,e)=>s+amountAt(e,month),0);
 const budgetStatus=data.budgets.map(b=>({...b,spent:categoryTotals.find(c=>c.category===b.category)?.total||0}));
 const nav:[View,string,React.ElementType][]=[['dashboard','Visão geral',LayoutDashboard],['cards','Cartões',CreditCard],['entries','Lançamentos',ArrowLeftRight],['calendar','Calendário',CalendarDays],['plan','Planejamento',Target],['reports','Relatórios',FileDown]];
