 async function submitCard(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),bank=String(f.get('bank'));const card:Card={id:editCard?.id??uid(),bank,name:String(f.get('name')||'').trim(),closing:Number(f.get('closing')),due:Number(f.get('due')),limit:toCents(f.get('limit')),color:banks[bank]||banks.Outro};if(await save({...data,cards:[...data.cards.filter(c=>c.id!==card.id),card]},'Cartão salvo')){setModal(null);setEditCard(null);}}
 async function submitSimple(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);if(modal==='settings'){await save({...data,salary:toCents(f.get('salary')),incomeStart:String(f.get('incomeStart')),reserve:Number(f.get('reserve'))});}if(modal==='budget'){const category=String(f.get('category')),budget:Budget={id:data.budgets.find(b=>b.category===category)?.id||uid(),category,limit:toCents(f.get('limit'))};await save({...data,budgets:[...data.budgets.filter(b=>b.category!==category),budget]},'Orçamento atualizado');}if(modal==='goal'){const goal:Goal={id:uid(),name:String(f.get('name')).trim(),target:toCents(f.get('target')),saved:toCents(f.get('saved')),deadline:String(f.get('deadline')),kind:String(f.get('kind')) as Goal['kind']};await save({...data,goals:[...data.goals,goal]},'Meta criada');}if(modal==='debt'){const debt:Debt={id:uid(),name:String(f.get('name')).trim(),balance:toCents(f.get('balance')),interest:Number(f.get('interest')),installment:toCents(f.get('installment')),remaining:Number(f.get('remaining')),dueDay:Number(f.get('dueDay'))};await save({...data,debts:[...data.debts,debt]},'Dívida adicionada');}if(modal==='category'){const name=String(f.get('name')).trim();if(name&&!data.customCategories.includes(name))await save({...data,customCategories:[...data.customCategories,name]},'Categoria criada');}setModal(null);}
 async function removeEntry(id:string){if(confirm('Excluir este lançamento?'))await save({...data,entries:data.entries.filter(e=>e.id!==id),paid:[]},'Lançamento excluído');}async function removeCard(id:string){if(confirm('Excluir o cartão e todos os lançamentos dele?'))await save({...data,cards:data.cards.filter(c=>c.id!==id),entries:data.entries.filter(e=>e.cardId!==id),paid:[]},'Cartão excluído');}
 function exportJson(){download(JSON.stringify({version:2,exportedAt:new Date().toISOString(),data},null,2),'application/json',`registro-financeiro-${month}.json`);}function exportCsv(){const rows=[['Data','Nome','Descrição','Categoria','Forma','Valor','Parcelas','Pessoa'],...data.entries.map(e=>[e.date,e.name,e.description,e.category,methodLabels[e.method],String(e.total/100),String(e.installments),e.borrower])];download(rows.map(r=>r.map(v=>`"${v.replaceAll('"','""')}"`).join(';')).join('\n'),'text/csv;charset=utf-8',`lancamentos-${month}.csv`);}function download(content:string,type:string,name:string){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
