  <div className="mb-6 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center rounded-xl border border-slate-200 bg-white p-1 shadow-sm"><button className="rounded-lg p-2 hover:bg-slate-100" onClick={()=>setMonth(addMonths(month,-1))}><ChevronLeft size={18}/></button><label className="relative flex min-w-40 items-center justify-center gap-2 px-2 text-sm font-semibold capitalize"><CalendarDays size={17} className="text-indigo-600"/>{monthLabel(month)}<input className="absolute inset-0 cursor-pointer opacity-0" type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label><button className="rounded-lg p-2 hover:bg-slate-100" onClick={()=>setMonth(addMonths(month,1))}><ChevronRight size={18}/></button></div><button onClick={()=>setMonth(current())} className="text-sm font-medium text-indigo-600">Ir para o mês atual</button></div>
